  1→import {
  2→  type ClientInterface,
  3→  type ClientProperties,
  4→  EncryptionState,
  5→  EncryptionSystem,
  6→  generateWebviewUrl,
  7→  HeaderStyle,
  8→  Intent,
  9→  makeWidgetDriver,
 10→  newVirtualElementCallWidget,
 11→  NotificationType,
 12→  type RoomInterface,
 13→  type VirtualElementCallWidgetConfig,
 14→  type VirtualElementCallWidgetProperties,
 15→  type WidgetCapabilitiesProvider,
 16→  type WidgetDriverAndHandle,
 17→  type WidgetSettings,
 18→} from "@unomed/react-native-matrix-sdk";
 19→
 20→export class ElementCallService {
 21→  private static widgetDrivers: Map<string, WidgetDriverAndHandle> = new Map();
 22→  private static activeCallRoomId: string | null = null;
 23→
 24→  static async createWidgetSettings(roomId: string, room: RoomInterface) {
 25→    try {
 26→      const encryptionState = await room.latestEncryptionState();
 27→      const isEncrypted = encryptionState === EncryptionState.Encrypted;
 28→
 29→      const options: VirtualElementCallWidgetProperties = {
 30→        elementCallUrl: "https://call.element.io/room",
 31→        widgetId: `element-call-${roomId}`,
 32→        fontScale: 1,
 33→        parentUrl: undefined,
 34→        font: undefined,
 35→        encryption: isEncrypted
 36→          ? new EncryptionSystem.PerParticipantKeys()
 37→          : new EncryptionSystem.Unencrypted(),
 38→        posthogApiHost: undefined,
 39→        posthogApiKey: undefined,
 40→        posthogUserId: undefined,
 41→        rageshakeSubmitUrl: undefined,
 42→        sentryDsn: undefined,
 43→        sentryEnvironment: undefined,
 44→      };
 45→
 46→      const config: VirtualElementCallWidgetConfig = {
 47→        hideHeader: true,
 48→        preload: false,
 49→        confineToRoom: true,
 50→        header: HeaderStyle.None,
 51→        appPrompt: false, // Hides "Open in App" prompt
 52→        hideScreensharing: false,
 53→        intent: Intent.StartCall,
 54→        sendNotificationType: NotificationType.Ring,
 55→        skipLobby: true,
 56→        controlledAudioDevices: false,
 57→      };
 58→
 59→      return newVirtualElementCallWidget(options, config);
 60→    } catch (error) {
 61→      console.error("Failed to create widget settings:", error);
 62→      throw error;
 63→    }
 64→  }
 65→
 66→  static async generateCallUrl(
 67→    widgetSettings: WidgetSettings,
 68→    room: RoomInterface,
 69→    _client: ClientInterface,
 70→  ) {
 71→    // Client properties for the widget (matching Swift implementation)
 72→    const clientProperties: ClientProperties = {
 73→      clientId: "io.element.elementx", // This allows widgets to adapt to specific clients
 74→      languageTag: "en-US", // Swift uses Locale.current
 75→      theme: "dark", // Swift checks colorScheme
 76→    };
 77→
 78→    try {
 79→      const url = await generateWebviewUrl(
 80→        widgetSettings,
 81→        room,
 82→        clientProperties,
 83→      );
 84→
 85→      return url;
 86→    } catch (error) {
 87→      console.error("Failed to generate Element Call URL:", error);
 88→      throw error;
 89→    }
 90→  }
 91→
 92→  static initializeWidgetDriver(
 93→    roomId: string,
 94→    widgetSettings: WidgetSettings,
 95→  ) {
 96→    const driverAndHandle = makeWidgetDriver(widgetSettings);
 97→    this.widgetDrivers.set(roomId, driverAndHandle);
 98→    return driverAndHandle;
 99→  }
100→
101→  static createCapabilitiesProvider() {
102→    const provider: WidgetCapabilitiesProvider = {
103→      acquireCapabilities: (requestedCapabilities) => {
104→        // Grant what the widget is requesting, not just the base permissions
105→        // The widget needs state keys with _m.call suffix, but getElementCallRequiredPermissions
106→        // only returns keys without the suffix
107→        // Return the REQUESTED capabilities (which includes the correct state keys)
108→        return requestedCapabilities;
109→      },
110→    };
111→
112→    return provider;
113→  }
114→
115→  static async startCall(
116→    roomId: string,
117→    room: RoomInterface,
118→    client: ClientInterface,
119→  ) {
120→    try {
121→      // Check if there's already an active driver for this room
122→      const existingDriver = this.widgetDrivers.get(roomId);
123→      if (existingDriver) {
124→        // Return existing driver instead of creating a new one
125→        const widgetSettings = await this.createWidgetSettings(roomId, room);
126→        const url = await this.generateCallUrl(widgetSettings, room, client);
127→        return { url, driverHandle: existingDriver };
128→      }
129→
130→      const widgetSettings = await this.createWidgetSettings(roomId, room);
131→
132→      const driverHandle = this.initializeWidgetDriver(roomId, widgetSettings);
133→
134→      const url = await this.generateCallUrl(widgetSettings, room, client);
135→
136→      const capabilitiesProvider = this.createCapabilitiesProvider();
137→
138→      driverHandle.driver.run(room, capabilitiesProvider).catch(console.error);
139→
140→      this.activeCallRoomId = roomId;
141→
142→      return { url, driverHandle };
143→    } catch (error) {
144→      console.error("Failed to start Element Call:", error);
145→      throw error;
146→    }
147→  }
148→
149→  static async endCall(roomId: string) {
150→    try {
151→      const driverHandle = this.widgetDrivers.get(roomId);
152→      if (driverHandle) {
153→        const widgetId = `element-call-${roomId}`;
154→
155→        try {
156→          // Send hangup message to Element Call
157→          // This tells Element Call to leave the LiveKit session and remove call.member state
158→          const hangupMessage = JSON.stringify({
159→            api: "fromWidget",
160→            widgetId: widgetId,
161→            requestId: `hangup-${Date.now()}`,
162→            action: "im.vector.hangup",
163→            data: {},
164→          });
165→
166→          await driverHandle.handle.send(hangupMessage);
167→
168→          await new Promise((resolve) => setTimeout(resolve, 1000));
169→
170→          // Send close message to ensure widget cleanup
171→          // This is similar to what Swift does with the "close" action
172→          const closeMessage = JSON.stringify({
173→            api: "fromWidget",
174→            widgetId: widgetId,
175→            requestId: `close-${Date.now()}`,
176→            action: "io.element.close",
177→            data: {},
178→          });
179→
180→          await driverHandle.handle.send(closeMessage);
181→
182→          await new Promise((resolve) => setTimeout(resolve, 500));
183→        } catch (err) {
184→          console.error("Failed to send end call messages:", err);
185→        }
186→
187→        // Cleanup driver
188→        this.widgetDrivers.delete(roomId);
189→      }
190→
191→      if (this.activeCallRoomId === roomId) this.activeCallRoomId = null;
192→    } catch (error) {
193→      console.error("Failed to end call:", error);
194→    }
195→  }
196→
197→  /**
198→   * Clean up driver without sending any messages
199→   * Use this when Element Call has already sent the hangup message
200→   */
201→  static async cleanupDriver(roomId: string) {
202→    this.widgetDrivers.delete(roomId);
203→    if (this.activeCallRoomId === roomId) this.activeCallRoomId = null;
204→  }
205→
206→  static getActiveCallRoomId() {
207→    return this.activeCallRoomId;
208→  }
209→
210→  static hasActiveCall() {
211→    return this.activeCallRoomId !== null;
212→  }
213→
214→  /**Send message to widget via driver handle */
215→  static async sendMessageToWidget(roomId: string, message: string) {
216→    const driverHandle = this.widgetDrivers.get(roomId);
217→
218→    if (!driverHandle) {
219→      console.warn("No driver handle found for room:", roomId);
220→      return;
221→    }
222→
223→    try {
224→      await driverHandle.handle.send(message);
225→    } catch (error) {
226→      console.error("Failed to send message to widget:", error);
227→      throw error;
228→    }
229→  }
230→
231→  static async receiveMessagesFromWidget(roomId: string) {
232→    const driverHandle = this.widgetDrivers.get(roomId);
233→
234→    if (!driverHandle) {
235→      console.warn("No driver handle found for room:", roomId);
236→      return;
237→    }
238→
239→    try {
240→      const message = await driverHandle.handle.recv();
241→      if (!message) throw new Error("No message received from widget");
242→
243→      return message;
244→    } catch (error) {
245→      console.error("Failed to receive message from widget:", error);
246→      throw error;
247→    }
248→  }
249→}
